/** Look up the role category for a given tag name. Returns null if unknown. */
export function getCategory(tagName) {
  if (!tagName) return null;
  return COMPONENT_CATEGORIES[tagName.toLowerCase()] || null;
}

/** Look up the composition tier (1–4) for a given tag name. Null if unknown. */
export function getTier(tagName) {
  if (!tagName) return null;
  return COMPONENT_TIERS[tagName.toLowerCase()] || null;
}
